import { SharedHeaderComponent } from './shared-header/shared-header.component';

@NgModule({
  declarations: [SharedHeaderComponent],
  imports: [CommonModule],
  exports: [SharedHeaderComponent]
})
export class SharedModule {}
```
This module declares the `SharedHeaderComponent` and exports it so that it can be used by other modules.

**Step 5: Import the shared module in the app module**

In the `app.module.ts` file, import the `SharedModule` and add it to the `Imports` array:
```
// app.module.ts
