```javascript
let heart;

function setup() {
  createCanvas(600, 600, WEBGL);
  heart = new Heart();
}

function draw() {
  background(255);
  translate(width / 2, height / 2);
  rotate(frameCount * 0.01);
  heart.draw();
}

class Heart {
  constructor() {
    this.sides = 3;
    this.step = 0.01;
    this.scale = 0.1;
    this.color = color('#FF0033'); // red
  }

  draw() {
    beginShape(TRIANGLES);
    for (let i = 0; i < this.sides; i++) {
      let angle = TWO_PI * i / this.sides;
      let x = sin(angle) * this.scale;
      let y = cos(angle) * this.scale;
      let aboveX = sin(angle + this.step) * this.scale;
      let aboveY = cos(angle + this.step) * this.scale;
      let belowX = sin(angle - this.step) * this.scale;
      let belowY = cos(angle - this.step) * this.scale;
      vertex(x, y, 0);
      vertex(aboveX, aboveY, 0);
      vertex(belowX, belowY, 0);
    }
    endShape();
  }
}
```
