native void Agent_OnUnload(JavaVM *vm);

void Agent_OnLoad(JavaVM *vm, char *options) {
    JNIEnv *env = NULL;
    if (vm->GetEnv((void**)&env, JNIVM_VERSION) != JNI_OK) {
        return;
    }
    jclass clazz;
    jmethodID method;
    clazz = env->FindClass("java/lang/Object");
    method = env->GetMethodID(clazz, "<init>", "()V");
    env->SetMethodID(clazz, "logCall", "(Ljava/lang/String;)V");
    env->GetMethodID(clazz, "logCall", "(Ljava/lang/String;)V");
}

void Agent_OnUnlaod(JavaVM *vm) {
    // nothing to do here
}

void logCall(JNIEnv *env, jobject thiz, jstring message) {
   LOGD("Method called: %s", env->GetStringUTFChars(message, NULL));
}
```
